-- Mobility sessions: first load of the authored content. Card 264.
-- GENERATED from mobile/supabase/seed/mobility.json by build-mobility-seed.mjs.
--
-- Safe to run once the 20260913000000_mobility_sessions migration is in.
-- Sessions are upserted by id and each listed session's moves are replaced,
-- so re-running it OVERWRITES any admin-console edit to these 8 sessions.
-- Once Emma is editing them in the console, export from there instead.

begin;

on conflict (id) do update set
  name = excluded.name,
  focus = excluded.focus,
  minutes = excluded.minutes,
  intensity = excluded.intensity,
  phases = excluded.phases,
  position = excluded.position;

delete from mobility_session_moves where session_id in ('wake-up', 'post-run-reset', 'wind-down', 'hips-and-lower-back', 'shoulders-and-upper-back', 'full-body-flow', 'deep-release', 'strong-and-supple');


commit;

notify pgrst, 'reload schema';
