insert into mobility_sessions (id, name, focus, minutes, intensity, phases, is_active, position)
values
  ('wake-up', 'Wake Up', 'Ten minutes to unstick the spine and hips before the day gets going.', 10, 'gentle', array['menstrual','follicular','ovulatory','luteal']::text[], true, 1),
  ('post-run-reset', 'Post-Run Reset', 'Calves, hips and hamstrings straight after a run, before they set.', 10, 'gentle', array['menstrual','follicular','ovulatory','luteal']::text[], true, 2),
  ('wind-down', 'Wind Down', 'Slow floor work and long breaths to settle the body before bed.', 10, 'gentle', array['menstrual','luteal']::text[], true, 3),
  ('hips-and-lower-back', 'Hips and Lower Back', 'Release for the hips and lower back on the days they take the strain.', 20, 'moderate', array['luteal','menstrual']::text[], true, 4),
  ('shoulders-and-upper-back', 'Shoulders and Upper Back', 'Open the chest and free the upper back from desk hours and tight arms.', 20, 'moderate', array['follicular','ovulatory']::text[], true, 5),
  ('full-body-flow', 'Full Body Flow', 'Standing to floor and back again, moving every joint through its range.', 20, 'moderate', array['follicular','ovulatory']::text[], true, 6),
  ('deep-release', 'Deep Release', 'Half an hour of unhurried floor work for the heaviest days.', 30, 'gentle', array['menstrual','luteal']::text[], true, 7),
  ('strong-and-supple', 'Strong and Supple', 'Range of movement with the control to hold it, Pilates style.', 30, 'strong', array['follicular','ovulatory']::text[], true, 8)
insert into mobility_session_moves (session_id, position, name, description, reps, sets, cue)
values
  ('wake-up', 1, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, 'Let the ribs widen sideways, not the belly.'),
  ('wake-up', 2, 'Pelvic Tilts', 'On your back with knees bent, rock the pelvis to flatten the lower back into the mat, then let it release into a small arch. Keep it small and slow.', '8 slow', null, null),
  ('wake-up', 3, 'Knee Hugs', 'On your back, hug both knees to the chest and rock gently side to side. Let the lower back soften into the mat.', '30s', null, null),
  ('wake-up', 4, 'Supine Twist', 'On your back, drop both knees to one side and turn the head the other way. Let the weight of the legs do the work.', '30s each side', null, null),
  ('wake-up', 5, 'Segmental Bridge', 'On your back, peel the spine off the mat from the tailbone up to a bridge, then lower one vertebra at a time.', '6 slow', null, null),
  ('wake-up', 6, 'Cat Cow', 'On hands and knees, round the spine toward the ceiling on the exhale, then let the chest and tailbone lift on the inhale. Move one vertebra at a time.', '8 slow', null, 'Let the breath set the pace.'),
  ('wake-up', 7, 'Thread the Needle', 'From hands and knees, slide one arm under the other and rest that shoulder on the mat, letting the upper back rotate. Keep the hips still.', '30s each side', null, null),
  ('wake-up', 8, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('wake-up', 9, 'Down Dog Pedal', 'In down dog, bend one knee and press the other heel toward the floor, alternating slowly.', '30s', null, null),
  ('wake-up', 10, 'Low Lunge', 'Step one foot forward and lower the back knee to the mat, sinking the hips forward. Keep the front knee over the ankle.', '30s each side', null, null),
  ('wake-up', 11, 'Deep Squat Hold', 'Feet slightly wider than the hips, sink into a full squat with heels down and elbows pressing the knees gently out. Keep the chest lifted.', '30s', null, 'Heels down. Hold something if you need to.'),
  ('wake-up', 12, 'Roll Down', 'Standing tall, nod the chin and roll down the spine one bone at a time until you hang, then restack from the tailbone up.', '4 slow', null, null),
  ('wake-up', 13, 'Shoulder Rolls', 'Stand or sit tall and roll the shoulders up, back and down in slow circles.', '8 each way', null, null),
  ('wake-up', 14, 'Neck Side Stretch', 'Sit tall and lower one ear toward the shoulder, with the opposite arm reaching down. Breathe into the side of the neck.', '20s each side', null, null),
  ('wake-up', 15, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, 'Standing this time. Notice what changed.'),
  ('post-run-reset', 1, 'Calf Stretch on Wall', 'Hands on a wall, step one foot back with the heel down and press it gently to the floor.', '30s each side', null, null),
  ('post-run-reset', 2, 'Standing Hamstring Stretch', 'Rest one heel on a low step and hinge forward from the hips with a flat back. Toes stay pointing up.', '30s each side', null, 'Hinge from the hips. The back stays flat.'),
  ('post-run-reset', 3, 'Half Kneeling Hip Flexor Stretch', 'Kneel on one knee with the other foot forward, tuck the tailbone and shift gently forward until the front of the kneeling hip lengthens.', '30s each side', null, 'Tuck the tailbone first, then shift forward.'),
  ('post-run-reset', 4, 'Half Split', 'From a low lunge, slide the hips back and straighten the front leg, folding over it with a long spine.', '30s each side', null, null),
  ('post-run-reset', 5, 'Down Dog Pedal', 'In down dog, bend one knee and press the other heel toward the floor, alternating slowly.', '30s', null, null),
  ('post-run-reset', 6, 'Pigeon', 'From hands and knees, bring one knee forward behind the wrist with the shin angled across, and fold over it. Keep the hips square.', '45s each side', null, null),
  ('post-run-reset', 7, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('post-run-reset', 8, 'Figure Four Stretch', 'On your back, cross one ankle over the opposite knee and draw the legs toward you. Keep the tailbone down.', '30s each side', null, null),
  ('post-run-reset', 9, 'Supine Twist', 'On your back, drop both knees to one side and turn the head the other way. Let the weight of the legs do the work.', '30s each side', null, null),
  ('post-run-reset', 10, 'Knee Hugs', 'On your back, hug both knees to the chest and rock gently side to side. Let the lower back soften into the mat.', '5 breaths', null, null),
  ('wind-down', 1, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '8 breaths', null, 'Make the exhale longer than the inhale.'),
  ('wind-down', 2, 'Pelvic Clocks', 'On your back, picture a clock face on the pelvis and tilt slowly toward each number in turn. The ribs stay heavy the whole way round.', '4 each way', null, null),
  ('wind-down', 3, 'Knee Hugs', 'On your back, hug both knees to the chest and rock gently side to side. Let the lower back soften into the mat.', '30s', null, null),
  ('wind-down', 4, 'Supine Twist', 'On your back, drop both knees to one side and turn the head the other way. Let the weight of the legs do the work.', '45s each side', null, null),
  ('wind-down', 5, 'Figure Four Stretch', 'On your back, cross one ankle over the opposite knee and draw the legs toward you. Keep the tailbone down.', '45s each side', null, null),
  ('wind-down', 6, 'Happy Baby', 'On your back, hold the outside of the feet with knees wide and draw them gently toward the armpits. Keep the tailbone heavy.', '30s', null, null),
  ('wind-down', 7, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '8 breaths', null, null),
  ('wind-down', 8, 'Shell Stretch', 'Kneel and fold forward onto the thighs with the arms by your sides, palms up. Let the back round completely.', '5 breaths', null, null),
  ('wind-down', 9, 'Sphinx', 'Face down with forearms on the mat, lift the chest and let the lower back settle into a gentle arch. Breathe into the front of the body.', '30s', null, 'Nothing forced. Let the lower back settle on its own.'),
  ('wind-down', 10, 'Butterfly', 'Sit with the soles of the feet together and knees open, and fold forward from the hips with a long spine.', '45s', null, null),
  ('wind-down', 11, 'Legs Up the Wall', 'Lie on your back with the legs resting up a wall and the arms open. Let the whole body go heavy.', '1 min', null, 'If there is no wall, rest the calves on a chair.'),
  ('wind-down', 12, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '8 breaths', null, null),
