  ('hips-and-lower-back', 4, 'Figure Four Stretch', 'On your back, cross one ankle over the opposite knee and draw the legs toward you. Keep the tailbone down.', '45s each side', null, null),
  ('hips-and-lower-back', 5, 'Supine Twist', 'On your back, drop both knees to one side and turn the head the other way. Let the weight of the legs do the work.', '45s each side', null, null),
  ('hips-and-lower-back', 6, 'Happy Baby', 'On your back, hold the outside of the feet with knees wide and draw them gently toward the armpits. Keep the tailbone heavy.', '30s', null, null),
  ('hips-and-lower-back', 7, 'Segmental Bridge', 'On your back, peel the spine off the mat from the tailbone up to a bridge, then lower one vertebra at a time.', '8 slow', null, 'One vertebra at a time, up and down.'),
  ('hips-and-lower-back', 8, 'Clam', 'Lie on your side with knees bent and feet together, and lift the top knee without rolling the pelvis back.', '10 each side', null, 'The pelvis stays stacked. Smaller is better.'),
  ('hips-and-lower-back', 9, 'Cat Cow', 'On hands and knees, round the spine toward the ceiling on the exhale, then let the chest and tailbone lift on the inhale. Move one vertebra at a time.', '8 slow', null, null),
  ('hips-and-lower-back', 10, 'Thread the Needle', 'From hands and knees, slide one arm under the other and rest that shoulder on the mat, letting the upper back rotate. Keep the hips still.', '30s each side', null, null),
  ('hips-and-lower-back', 11, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('hips-and-lower-back', 12, 'Adductor Rock Back', 'On hands and knees, extend one leg out to the side with the foot flat, and rock the hips back and forward over the kneeling leg.', '8 each side', null, null),
  ('hips-and-lower-back', 13, 'Frog Stretch', 'On hands and knees, widen the knees and turn the feet out, then rock the hips gently back toward the heels.', '45s', null, null),
  ('hips-and-lower-back', 14, '90/90 Hip Switch', 'Sit with one leg bent in front and one behind, both at right angles, and rotate the knees from one side to the other. Stay tall.', '8 slow', null, null),
  ('hips-and-lower-back', 15, '90/90 Forward Fold', 'In the 90/90 seat, hinge the chest forward over the front shin and breathe into the outer hip.', '45s each side', null, null),
  ('hips-and-lower-back', 16, 'Pigeon', 'From hands and knees, bring one knee forward behind the wrist with the shin angled across, and fold over it. Keep the hips square.', '45s each side', null, 'Hips square. A cushion under the hip is fine.'),
  ('hips-and-lower-back', 17, 'Half Kneeling Hip Flexor Stretch', 'Kneel on one knee with the other foot forward, tuck the tailbone and shift gently forward until the front of the kneeling hip lengthens.', '45s each side', null, null),
  ('hips-and-lower-back', 18, 'Lizard', 'From a low lunge, walk the front foot out wide and lower the forearms toward the mat inside the leg.', '45s each side', null, null),
  ('hips-and-lower-back', 19, 'Butterfly', 'Sit with the soles of the feet together and knees open, and fold forward from the hips with a long spine.', '45s', null, null),
  ('hips-and-lower-back', 20, 'Spine Stretch Forward', 'Sit tall with legs straight and hip-width apart, then reach forward over the legs, peeling the spine into a long curve. Draw the belly back as you fold.', '5 slow', null, null),
  ('hips-and-lower-back', 21, 'Saw', 'Sit tall with legs wide and arms out, rotate and reach the little finger past the opposite little toe, then return. Keep both hips heavy.', '5 each side', null, null),
  ('hips-and-lower-back', 22, 'Mermaid', 'Sit with the legs folded to one side, reach the opposite arm overhead and lean over the folded legs, then counter-stretch the other way.', '30s each side', null, null),
  ('hips-and-lower-back', 23, 'Squat & Reach', 'Hold a deep squat and reach one arm overhead, opening through the upper back.', '6 each side', null, null),
  ('hips-and-lower-back', 24, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null),
  ('shoulders-and-upper-back', 1, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null),
  ('shoulders-and-upper-back', 2, 'Chin Tucks', 'Sit tall and glide the chin straight back as if making a double chin, lengthening the back of the neck.', '8 slow', null, null),
  ('shoulders-and-upper-back', 3, 'Neck Side Stretch', 'Sit tall and lower one ear toward the shoulder, with the opposite arm reaching down. Breathe into the side of the neck.', '20s each side', null, null),
  ('shoulders-and-upper-back', 4, 'Shoulder Rolls', 'Stand or sit tall and roll the shoulders up, back and down in slow circles.', '8 each way', null, null),
  ('shoulders-and-upper-back', 5, 'Arm Circles', 'Stand tall and circle the arms slowly in both directions, keeping the ribs still.', '8 each way', null, null),
  ('shoulders-and-upper-back', 6, 'Wall Angels', 'Back against a wall with the arms in a goalpost, slide them up and down the wall keeping the wrists and elbows in contact.', '8 slow', null, 'Ribs stay on the wall. Go only as high as that allows.'),
  ('shoulders-and-upper-back', 7, 'Doorway Pec Stretch', 'Forearm on a doorframe at shoulder height, step gently through until the chest opens. Keep the ribs down.', '30s each side', null, null),
  ('shoulders-and-upper-back', 8, 'Chest Opener Hands Clasped', 'Stand tall, clasp the hands behind the back and draw them down and away, lifting the chest.', '30s', null, null),
  ('shoulders-and-upper-back', 9, 'Cat Cow', 'On hands and knees, round the spine toward the ceiling on the exhale, then let the chest and tailbone lift on the inhale. Move one vertebra at a time.', '8 slow', null, null),
  ('shoulders-and-upper-back', 10, 'Thoracic Rotation on All Fours', 'On hands and knees, place one hand behind the head and rotate the elbow toward the ceiling, then down toward the opposite wrist.', '8 each side', null, null),
  ('shoulders-and-upper-back', 11, 'Thread the Needle', 'From hands and knees, slide one arm under the other and rest that shoulder on the mat, letting the upper back rotate. Keep the hips still.', '45s each side', null, null),
  ('shoulders-and-upper-back', 12, 'Scapular Push-ups', 'On hands and knees or in a plank, let the shoulder blades draw together, then push the floor away to spread them. The elbows stay straight.', '10 slow', null, null),
  ('shoulders-and-upper-back', 13, 'Puppy Pose', 'From hands and knees, walk the hands forward and lower the chest toward the mat with the hips high over the knees.', '45s', null, null),
  ('shoulders-and-upper-back', 14, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('shoulders-and-upper-back', 15, 'Book Openings', 'Lie on your side with knees bent and arms stacked in front, then lift the top arm and open it behind you like a book, following it with your eyes. Keep the knees pressed together.', '8 each side', null, 'Follow the hand with your eyes. Knees stay glued.'),
  ('shoulders-and-upper-back', 16, 'Prone Y-Raise', 'Face down with arms overhead in a Y, lift the thumbs toward the ceiling and squeeze the lower traps.', '8 slow', null, null),
  ('shoulders-and-upper-back', 17, 'Prone W-Raise', 'Face down with elbows tucked into a W, lift the hands and squeeze the shoulder blades together.', '8 slow', null, null),
  ('shoulders-and-upper-back', 18, 'Prone T-Raise', 'Pull toward the face with elbows high, squeezing the rear shoulders and upper back.', '8 slow', null, null),
  ('shoulders-and-upper-back', 19, 'Swan Prep', 'Lie face down with hands under the shoulders and lift the chest by lengthening the spine forward and up, not by pressing hard. Keep the neck long.', '6 slow', null, 'Length first, height second.'),
  ('shoulders-and-upper-back', 20, 'Swimming Prep', 'Face down, lift the opposite arm and leg a few inches while the belly stays lifted, then swap sides.', '8 each side', null, null),
  ('shoulders-and-upper-back', 21, 'Cobra', 'Face down with hands under the shoulders, press up through the hands to lift the chest while the hips stay on the mat.', '5 breaths', null, null),
  ('shoulders-and-upper-back', 22, 'Shell Stretch', 'Kneel and fold forward onto the thighs with the arms by your sides, palms up. Let the back round completely.', '5 breaths', null, null),
  ('shoulders-and-upper-back', 23, 'Thoracic Extension over Bolster', 'Lie back over a rolled towel or bolster placed under the shoulder blades, hands behind the head, and let the upper back open. Keep the ribs soft.', '1 min', null, null),
  ('shoulders-and-upper-back', 24, 'Spine Twist Seated', 'Sit tall with legs together and arms out, and rotate the ribcage one way and back, growing taller as you turn. The hips stay still.', '6 each side', null, null),
  ('shoulders-and-upper-back', 25, 'Mermaid', 'Sit with the legs folded to one side, reach the opposite arm overhead and lean over the folded legs, then counter-stretch the other way.', '30s each side', null, null),
  ('shoulders-and-upper-back', 26, 'World''s Greatest Stretch', 'Lunge forward, drop the opposite elbow to your instep, then rotate the chest open.', '5 each side', null, null),
  ('shoulders-and-upper-back', 27, 'Roll Down', 'Standing tall, nod the chin and roll down the spine one bone at a time until you hang, then restack from the tailbone up.', '4 slow', null, null),
  ('shoulders-and-upper-back', 28, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null),
  ('full-body-flow', 1, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null),
  ('full-body-flow', 2, 'Roll Down', 'Standing tall, nod the chin and roll down the spine one bone at a time until you hang, then restack from the tailbone up.', '4 slow', null, null),
  ('full-body-flow', 3, 'Standing Hip Circles', 'Stand on one leg with a hand on a wall and circle the free knee out and around. Keep the standing hip steady.', '6 each way', null, null),
  ('full-body-flow', 4, 'Leg Swings', 'Holding a wall, swing one leg forward and back from the hip with a relaxed knee. Let the range build over the reps.', '10 each side', null, null),
  ('full-body-flow', 5, 'Deep Squat Hold', 'Feet slightly wider than the hips, sink into a full squat with heels down and elbows pressing the knees gently out. Keep the chest lifted.', '30s', null, null),
  ('full-body-flow', 6, 'Squat & Reach', 'Hold a deep squat and reach one arm overhead, opening through the upper back.', '6 each side', null, null),
  ('full-body-flow', 7, 'World''s Greatest Stretch', 'Lunge forward, drop the opposite elbow to your instep, then rotate the chest open.', '5 each side', null, null),
  ('full-body-flow', 8, 'Cossack Squat', 'Step wide and sink toward one heel with the other leg straight and its toes up, then shift across to the other side.', '6 each side', null, 'Only as low as the heel stays down.'),
  ('full-body-flow', 9, 'Low Lunge Twist', 'In a low lunge, place the opposite hand on the floor and rotate the chest toward the front leg, reaching the free arm up.', '30s each side', null, null),
  ('full-body-flow', 10, 'Lizard', 'From a low lunge, walk the front foot out wide and lower the forearms toward the mat inside the leg.', '30s each side', null, 'Range is easy to find today. Stop where the stretch is clear, not where it ends.'),
  ('full-body-flow', 11, 'Down Dog', 'From hands and knees, lift the hips high into an upside-down V, pressing the chest toward the thighs. Bend the knees as much as you need.', '5 breaths', null, null),
  ('full-body-flow', 12, 'Down Dog Pedal', 'In down dog, bend one knee and press the other heel toward the floor, alternating slowly.', '30s', null, null),
  ('full-body-flow', 13, 'Plank to Down Dog', 'From a plank, push the hips up and back into down dog, then return to plank without the shoulders collapsing.', '6 slow', null, null),
  ('full-body-flow', 14, 'Cat Cow', 'On hands and knees, round the spine toward the ceiling on the exhale, then let the chest and tailbone lift on the inhale. Move one vertebra at a time.', '8 slow', null, null),
  ('full-body-flow', 15, 'Thoracic Rotation on All Fours', 'On hands and knees, place one hand behind the head and rotate the elbow toward the ceiling, then down toward the opposite wrist.', '6 each side', null, null),
  ('full-body-flow', 16, 'Bird Dog', 'On hands and knees, reach the opposite arm and leg long without the hips rotating, then swap.', '6 each side', null, null),
  ('full-body-flow', 17, 'Frog Stretch', 'On hands and knees, widen the knees and turn the feet out, then rock the hips gently back toward the heels.', '30s', null, null),
  ('full-body-flow', 18, 'Pigeon', 'From hands and knees, bring one knee forward behind the wrist with the shin angled across, and fold over it. Keep the hips square.', '45s each side', null, null),
  ('full-body-flow', 19, '90/90 Hip Switch', 'Sit with one leg bent in front and one behind, both at right angles, and rotate the knees from one side to the other. Stay tall.', '8 slow', null, null),
  ('full-body-flow', 20, 'Swan Prep', 'Lie face down with hands under the shoulders and lift the chest by lengthening the spine forward and up, not by pressing hard. Keep the neck long.', '6 slow', null, null),
  ('full-body-flow', 21, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('full-body-flow', 22, 'Rolling Like a Ball', 'Sit balanced just behind the tailbone, hold the shins, and roll back to the shoulders and up again without the head touching down. Stay round.', '6', null, 'Stay round. The head never touches down.'),
  ('full-body-flow', 23, 'Spine Stretch Forward', 'Sit tall with legs straight and hip-width apart, then reach forward over the legs, peeling the spine into a long curve. Draw the belly back as you fold.', '5 slow', null, null),
