  ('deep-release', 13, 'Shell Stretch', 'Kneel and fold forward onto the thighs with the arms by your sides, palms up. Let the back round completely.', '8 breaths', null, null),
  ('deep-release', 14, 'Frog Stretch', 'On hands and knees, widen the knees and turn the feet out, then rock the hips gently back toward the heels.', '45s', null, null),
  ('deep-release', 15, 'Half Kneeling Hip Flexor Stretch', 'Kneel on one knee with the other foot forward, tuck the tailbone and shift gently forward until the front of the kneeling hip lengthens.', '45s each side', null, null),
  ('deep-release', 16, 'Lizard', 'From a low lunge, walk the front foot out wide and lower the forearms toward the mat inside the leg.', '45s each side', null, null),
  ('deep-release', 17, 'Pigeon', 'From hands and knees, bring one knee forward behind the wrist with the shin angled across, and fold over it. Keep the hips square.', '45s each side', null, 'Prop the hip if it needs it. Comfort is the point today.'),
  ('deep-release', 18, '90/90 Forward Fold', 'In the 90/90 seat, hinge the chest forward over the front shin and breathe into the outer hip.', '45s each side', null, null),
  ('deep-release', 19, 'Butterfly', 'Sit with the soles of the feet together and knees open, and fold forward from the hips with a long spine.', '45s', null, null),
  ('deep-release', 20, 'Mermaid', 'Sit with the legs folded to one side, reach the opposite arm overhead and lean over the folded legs, then counter-stretch the other way.', '45s each side', null, null),
  ('deep-release', 21, 'Standing Roll Down with Knee Bend', 'Roll down as before, soften the knees at the bottom so the lower back can let go, then restack from the tailbone.', '4 slow', null, null),
  ('deep-release', 22, 'Calf Stretch on Wall', 'Hands on a wall, step one foot back with the heel down and press it gently to the floor.', '30s each side', null, null),
  ('deep-release', 23, 'Doorway Pec Stretch', 'Forearm on a doorframe at shoulder height, step gently through until the chest opens. Keep the ribs down.', '30s each side', null, null),
  ('deep-release', 24, 'Chest Opener Hands Clasped', 'Stand tall, clasp the hands behind the back and draw them down and away, lifting the chest.', '30s', null, null),
  ('deep-release', 25, 'Neck Side Stretch', 'Sit tall and lower one ear toward the shoulder, with the opposite arm reaching down. Breathe into the side of the neck.', '30s each side', null, null),
  ('deep-release', 26, 'Thoracic Extension over Bolster', 'Lie back over a rolled towel or bolster placed under the shoulder blades, hands behind the head, and let the upper back open. Keep the ribs soft.', '45s', null, null),
  ('deep-release', 27, 'Knee Hugs', 'On your back, hug both knees to the chest and rock gently side to side. Let the lower back soften into the mat.', '30s', null, null),
  ('deep-release', 28, 'Legs Up the Wall', 'Lie on your back with the legs resting up a wall and the arms open. Let the whole body go heavy.', '1 min', null, null),
  ('deep-release', 29, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '10 breaths', null, null),
  ('strong-and-supple', 1, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null),
  ('strong-and-supple', 2, 'Roll Down', 'Standing tall, nod the chin and roll down the spine one bone at a time until you hang, then restack from the tailbone up.', '4 slow', null, null),
  ('strong-and-supple', 3, 'Standing Single Leg Balance', 'Stand on one leg with the hips level and hold, eyes fixed on one point. Let the foot do the work.', '30s each side', null, null),
  ('strong-and-supple', 4, 'Standing Hip Airplane', 'Hinge over one leg with the other reaching behind, then rotate the pelvis open and closed over the standing hip. Small and controlled.', '5 each side', null, 'Tiny range. The standing knee stays soft.'),
  ('strong-and-supple', 5, 'Deep Squat Hold', 'Feet slightly wider than the hips, sink into a full squat with heels down and elbows pressing the knees gently out. Keep the chest lifted.', '30s', null, null),
  ('strong-and-supple', 6, 'World''s Greatest Stretch', 'Lunge forward, drop the opposite elbow to your instep, then rotate the chest open.', '5 each side', null, null),
  ('strong-and-supple', 7, 'Low Lunge Twist', 'In a low lunge, place the opposite hand on the floor and rotate the chest toward the front leg, reaching the free arm up.', '30s each side', null, null),
  ('strong-and-supple', 8, 'Lizard', 'From a low lunge, walk the front foot out wide and lower the forearms toward the mat inside the leg.', '30s each side', null, 'Range comes easily this week. Stop where the stretch is clear, not where it ends.'),
  ('strong-and-supple', 9, 'Plank to Down Dog', 'From a plank, push the hips up and back into down dog, then return to plank without the shoulders collapsing.', '6 slow', null, null),
  ('strong-and-supple', 10, 'Bird Dog', 'On hands and knees, reach the opposite arm and leg long without the hips rotating, then swap.', '8 each side', null, null),
  ('strong-and-supple', 11, 'Thoracic Rotation on All Fours', 'On hands and knees, place one hand behind the head and rotate the elbow toward the ceiling, then down toward the opposite wrist.', '8 each side', null, null),
  ('strong-and-supple', 12, '90/90 Hip Switch', 'Sit with one leg bent in front and one behind, both at right angles, and rotate the knees from one side to the other. Stay tall.', '8 slow', null, null),
  ('strong-and-supple', 13, 'Pigeon', 'From hands and knees, bring one knee forward behind the wrist with the shin angled across, and fold over it. Keep the hips square.', '45s each side', null, null),
  ('strong-and-supple', 14, 'Hundred Prep', 'On your back, curl the head and shoulders up with the legs in tabletop and pump the arms as you breathe in for five and out for five.', '5 breaths', null, 'In for five, out for five. Ribs stay down.'),
  ('strong-and-supple', 15, 'Single Leg Stretch', 'Curl up, hug one knee in while the other leg reaches long, and switch. The lower back stays on the mat.', '10 each side', null, null),
  ('strong-and-supple', 16, 'Criss Cross', 'Curl up with hands behind the head and rotate the ribcage toward the bent knee as the other leg reaches long.', '10 each side', null, null),
  ('strong-and-supple', 17, 'Dead Bug', 'On your back, extend the opposite arm and leg while pressing the low back into the floor, resisting any twist.', '8 each side', null, null),
  ('strong-and-supple', 18, 'Roll Up', 'Lie long, reach the arms to the ceiling and roll up through the spine to reach for the toes, then roll back down with control.', '6 slow', null, 'Bend the knees if the lower back lifts off.'),
  ('strong-and-supple', 19, 'Spine Stretch Forward', 'Sit tall with legs straight and hip-width apart, then reach forward over the legs, peeling the spine into a long curve. Draw the belly back as you fold.', '5 slow', null, null),
  ('strong-and-supple', 20, 'Saw', 'Sit tall with legs wide and arms out, rotate and reach the little finger past the opposite little toe, then return. Keep both hips heavy.', '5 each side', null, null),
  ('strong-and-supple', 21, 'Teaser Prep', 'Sit balanced on the back of the pelvis with knees bent, reach the arms forward, and extend one leg to match the angle of the other thigh.', '5 each side', null, null),
  ('strong-and-supple', 22, 'Mermaid', 'Sit with the legs folded to one side, reach the opposite arm overhead and lean over the folded legs, then counter-stretch the other way.', '30s each side', null, null),
  ('strong-and-supple', 23, 'Side Kick Series', 'Lie on your side with the top leg hovering and sweep it forward and back without the torso moving.', '10 each side', null, null),
  ('strong-and-supple', 24, 'Clam', 'Lie on your side with knees bent and feet together, and lift the top knee without rolling the pelvis back.', '12 each side', null, null),
  ('strong-and-supple', 25, 'Side Plank', 'Forearm or hand down, lift the hips to make one straight line from head to feet.', '30s each side', null, 'Knee down is a full version, not a lesser one.'),
  ('strong-and-supple', 26, 'Segmental Bridge', 'On your back, peel the spine off the mat from the tailbone up to a bridge, then lower one vertebra at a time.', '8 slow', null, null),
  ('strong-and-supple', 27, 'Shoulder Bridge with Leg Lift', 'Hold a bridge and float one leg toward the ceiling, keeping the hips level, then lower and swap.', '6 each side', null, null),
  ('strong-and-supple', 28, 'Single Leg Circles', 'On your back, reach one leg to the ceiling and draw circles across the body and back around. Keep the pelvis still.', '6 each way, each side', null, null),
  ('strong-and-supple', 29, 'Swan Prep', 'Lie face down with hands under the shoulders and lift the chest by lengthening the spine forward and up, not by pressing hard. Keep the neck long.', '6 slow', null, null),
  ('strong-and-supple', 30, 'Swimming', 'Face down, lift the opposite arm and leg and flutter them in a small quick beat while breathing steadily. The belly stays lifted.', '30s', null, null),
  ('strong-and-supple', 31, 'Cobra', 'Face down with hands under the shoulders, press up through the hands to lift the chest while the hips stay on the mat.', '5 breaths', null, null),
  ('strong-and-supple', 32, 'Child''s Pose', 'Knees wide, big toes together, sit back toward the heels and reach the arms long. Let the forehead rest and the breath slow.', '5 breaths', null, null),
  ('strong-and-supple', 33, 'Thread the Needle', 'From hands and knees, slide one arm under the other and rest that shoulder on the mat, letting the upper back rotate. Keep the hips still.', '30s each side', null, null),
  ('strong-and-supple', 34, 'Supine Twist', 'On your back, drop both knees to one side and turn the head the other way. Let the weight of the legs do the work.', '30s each side', null, null),
  ('strong-and-supple', 35, 'Knee Hugs', 'On your back, hug both knees to the chest and rock gently side to side. Let the lower back soften into the mat.', '30s', null, null),
  ('strong-and-supple', 36, 'Lateral Breathing', 'Lie or sit tall with the hands on the ribs and breathe wide into the sides of the ribcage, letting the belly stay quiet. Exhale fully and feel the ribs knit down.', '5 breaths', null, null);
